/** How an attribute's value is entered: `object` is a value object, the rest are single values. */
export type Kind = "text" | "integer" | "number" | "boolean" | "object" | "reference";

/**
 * What an attribute names: an instance of another aggregate, offered as a choice. `strict` pickers
 * accept only a key that exists; the others suggest and accept any text. `listing` is the query of
 * the target that lists what is on offer, or none to offer every instance. With `kinds`, the value is
 * `<kind>:<key>`: the kind is chosen first, then the record of the aggregate that kind names.
 */
export interface Picker {
  target?: string;
  /** The target's chapter, when the editor spans several or the target is in another. */
  chapter?: string;
  /** The target's identity attribute. */
  key?: string;
  /** The attribute that names an instance to a person (its title, name or label, else its identity). */
  label?: string;
  listing?: string;
  strict?: boolean;
  kinds?: PickerKind[];
}

/** One kind of a `<kind>:<key>` value, and the aggregate it names when it names one. */
export type PickerKind = Omit<Picker, "kinds"> & { kind: string };

export interface Attr {
  name: string;
  /** The type as the bluebook spells it ("String", "Byline"). */
  type: string;
  kind: Kind;
  optional: boolean;
  /** True for `list_of`: the attribute holds a list of `type`. */
  list: boolean;
  /**
   * `body` for an attribute whose value object has the shape of a structured document (blocks of
   * spans); `date` or `datetime` for whole seconds since 1970 that the names say are a moment.
   */
  widget?: "body" | "date" | "datetime";
  /** Set when the attribute names an instance of another aggregate of the editor. */
  picker?: Picker;
  /** The members of the closed set the attribute is one of, when its value object declares one. */
  options?: string[];
  /** The aggregate a `reference` points at. */
  target?: string;
}

export interface Transition {
  verb: string;
  from: string[];
  to: string;
}

export interface Lifecycle {
  field: string;
  default: string;
  transitions: Transition[];
  /** Each state's badge tone: `neutral`, `ok`, `info`, `warn` or `danger`. */
  tones: Record<string, string>;
}

export interface Command {
  name: string;
  goal: string | null;
  role: string | null;
  /** True when the command makes a new instance; false when it acts on one (`reference_to`). */
  creates: boolean;
  /** The aggregate the command acts on, when it is not a creating command. */
  on: string | null;
  /** True when the editor asks for confirmation before running it (see the generator's `Destructive`). */
  destructive: boolean;
  attributes: Attr[];
  /** The arguments that only clear a field and are not offered as inputs: sent as empty lists. */
  empty?: string[];
}

export interface Query {
  name: string;
  description: string | null;
  attributes: Attr[];
}

/**
 * A record of another aggregate that goes with this one's records, because its identity is a
 * `<kind>:<slug>` key of this aggregate. `shape` says how to show it; `create` and `edit` name the
 * commands that make and change it, when it has them.
 */
export interface Related {
  aggregate: string;
  chapter?: string;
  /** The related aggregate's identity attribute, which the key fills. */
  field: string;
  shape: "document" | "gallery" | "metadata";
  create?: string;
  edit?: string;
}

/** An aggregate that keeps a draft of a body beside the live one, and the commands that handle it. */
export interface Drafts {
  /** The draft attribute (`draft_body`) and the live one it stands for (`body`). */
  attribute: string;
  live: string;
  save: string;
  publish?: string;
  discard?: string;
}

export interface Aggregate {
  name: string;
  /** The chapter that declares the aggregate; set when the editor spans several. */
  chapter?: string;
  /** The roles that may edit it, when its chapter limits them; any admitted role otherwise. */
  roles?: string[];
  description: string | null;
  identity: string;
  lifecycle: Lifecycle | null;
  attributes: Attr[];
  valueObjects: Record<string, Attr[]>;
  commands: Command[];
  queries: Query[];
  /** The aggregates keyed by this one's records, shown as panels on a record's page. */
  related?: Related[];
  /** The draft the aggregate keeps beside a live body, when it keeps one. */
  drafts?: Drafts;
}

/** How one part of a picture's record is sent: `wrap` is the part of a value object that holds the value. */
export interface MediaField {
  name: string;
  wrap: string | null;
}

/** The aggregate that registers pictures, when the chapter has one: found by shape, never by name. */
export interface Media {
  aggregate: string;
  command: string;
  fields: { key: MediaField; alt: MediaField; mime: MediaField; width?: MediaField; height?: MediaField };
  /** The query that lists the pictures, or null when every instance is read. */
  listing: string | null;
  /** The chapter that holds the picture aggregate, when it is not this editor's own chapter. */
  domain?: string;
  /** That aggregate, which is then not among the editor's own; see `domain`. */
  definition?: Aggregate;
}

/**
 * The aggregate whose records are actions to run later, found by shape: the attribute that names the
 * record an action is for, the closed set of actions, the due time, and the commands. The editor only
 * makes and changes these records; something else runs them.
 */
export interface Scheduling {
  aggregate: string;
  chapter?: string;
  subject: string;
  action: string;
  actions: string[];
  due: string;
  /** The first state of a record: an action not yet run. */
  pending: string;
  schedule: string;
  reschedule?: string;
  cancel?: string;
  /** The query that lists the actions of one subject, when there is one. */
  query?: string;
  /** The optional text a record may carry to say why it ended as it did. */
  reason?: string;
  /** True when the editor makes the record's identity, since it is not the subject. */
  generated?: boolean;
}

